use std::sync::atomic::{AtomicBool, Ordering};

// ❌ OLD: Publishing data with a Relaxed flag. The flag store is
// atomic, but Relaxed gives NO ordering guarantee — the reader who
// sees READY == true is NOT guaranteed to see the DATA written before
// it. On a weak-memory CPU (ARM), the reader may observe stale data.
static READY: AtomicBool = AtomicBool::new(false);
static mut DATA: [u8; 8] = [0; 8];

fn writer() {
    unsafe { DATA.copy_from_slice(&[1, 2, 3, 4, 5, 6, 7, 8]) }
    READY.store(true, Ordering::Relaxed); // ❌ OLD: no ordering edge
}

fn reader() -> bool {
    if READY.load(Ordering::Relaxed) { // ❌ OLD: may see stale DATA
        return unsafe { DATA[0] == 1 };
    }
    false
}

use std::sync::atomic::{AtomicBool, Ordering};

// ✅ NEW: Release/Acquire creates a happens-before edge. When the
// reader's Acquire load observes the writer's Release store, ALL
// writes the writer performed BEFORE the Release (the DATA copy) are
// guaranteed visible.
static READY: AtomicBool = AtomicBool::new(false);
static mut DATA: [u8; 8] = [0; 8];

fn writer() {
    unsafe { DATA.copy_from_slice(&[1, 2, 3, 4, 5, 6, 7, 8]) }
    READY.store(true, Ordering::Release); // ✅ NEW: publish data + flag
}

fn reader() -> bool {
    if READY.load(Ordering::Acquire) { // ✅ NEW: acquires the published data
        return unsafe { DATA[0] == 1 }; // ✅ NEW: guaranteed to see the copy
    }
    false
}

// Use Relaxed only for pure counters (stats) where no other data is
// being coordinated:
// COUNTER.fetch_add(1, Ordering::Relaxed);
// SeqCst is for global-order coordination (rare); prefer the cheaper
// Acquire/Release when the pattern is publish/consume.
